styles.css.data:
.navopath-plugin-settings { display: grid; gap: 16px; color: var(--text-main); }
.navopath-plugin-settings label { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.navopath-plugin-settings input, .navopath-plugin-settings select, .navopath-plugin-settings button { font: inherit; color: inherit; background: var(--surface-main); border: 1px solid var(--border-soft); border-radius: 4px; padding: 8px; min-height: 34px; }
.navopath-plugin-settings input:focus-visible, .navopath-plugin-settings select:focus-visible, .navopath-plugin-settings button:focus-visible { outline: 2px solid var(--accent-active); outline-offset: 2px; }
@media (pointer: coarse) { .navopath-plugin-settings input, .navopath-plugin-settings select, .navopath-plugin-settings button { min-height: 44px; } }
.navopath-weather { position: relative; color: var(--text-main); font: inherit; }
.navopath-weather-summary { display: flex; align-items: center; gap: 6px; min-height: 34px; padding: 4px; cursor: pointer; list-style: none; white-space: nowrap; }
.navopath-weather-summary::-webkit-details-marker { display: none; }
.navopath-weather-summary:focus-visible, .navopath-weather-details button:focus-visible { outline: 2px solid var(--accent-active); outline-offset: 2px; }
.navopath-weather-city { max-width: 130px; overflow: hidden; text-overflow: ellipsis; }
.navopath-weather-details { position: absolute; z-index: 40; right: 0; top: calc(100% + 8px); width: min(280px, calc(100vw - 32px)); padding: 16px; color: var(--text-main); background: var(--surface-raised, var(--surface-main)); border: 1px solid var(--border-soft); border-radius: 4px; white-space: normal; font-size: 13px; }
.navopath-weather-details p { margin: 0 0 12px; }
.navopath-weather-details dl { display: grid; gap: 8px; margin: 0 0 12px; }
.navopath-weather-details dl div, .navopath-weather-actions { display: flex; justify-content: space-between; gap: 12px; }
.navopath-weather-details dd { margin: 0; }
.navopath-weather-details time { display: block; color: var(--text-muted); }
.navopath-weather-actions { align-items: center; margin-top: 12px; }
.navopath-weather-actions button { font: inherit; color: inherit; background: transparent; padding: 6px 10px; border: 1px solid var(--border-soft); border-radius: 4px; }
.navopath-weather-actions a { color: inherit; text-underline-offset: 3px; }
.navopath-weather-error { color: var(--danger-ink); overflow-wrap: anywhere; }
.navopath-weather[data-stale="true"] summary { text-decoration: underline dotted; }
@media (max-width: 680px) { .navopath-weather-city { max-width: 75px; } }
@media (pointer: coarse) { .navopath-weather-summary, .navopath-weather-actions button { min-height: 44px; } }

.navopath-plugin-settings input[type="checkbox"] { width: 18px; height: 18px; min-height: 18px; padding: 0; flex: 0 0 auto; accent-color: var(--accent-active); }
.navopath-plugin-settings label > input:not([type="checkbox"]), .navopath-plugin-settings label > select { width: min(220px, 55%); }
